has_independence_wave_form48_current_autonomous_binding = {
	has_country_flag = independence_wave_form48_autonomous_member
	has_variable = independence_wave_generation_id
	has_variable = independence_wave_form48_autonomous_carrier
	has_variable = independence_wave_form48_autonomous_carrier_generation
	has_variable = independence_wave_form48_autonomous_member_generation
	has_variable = independence_wave_form48_autonomous_family
	check_variable = { independence_wave_form48_autonomous_family = constant:independence_wave_formable_family.pacific_regional_federation }
	check_variable = { var = independence_wave_generation_id value = independence_wave_form48_autonomous_member_generation compare = equals }
	var:independence_wave_form48_autonomous_carrier = {
		exists = yes
		has_variable = independence_wave_generation_id
		has_variable = independence_wave_formable_family
		check_variable = { independence_wave_formable_family = constant:independence_wave_formable_family.pacific_regional_federation }
		check_variable = { var = independence_wave_generation_id value = PREV.independence_wave_form48_autonomous_carrier_generation compare = equals }
	}
}

independence_wave_form48_cleanup_frozen_autonomous_members = {
	if = {
		limit = { independence_wave_formable_member_arrays_are_aligned = yes }
		set_temp_variable = { independence_wave_form48_cleanup_member_index = constant:independence_wave_formable_tuning.first_array_index }
		while_loop_effect = {
			limit = { check_variable = { var = independence_wave_form48_cleanup_member_index value = independence_wave_formable_member_country_entries^num compare = less_than } }
			var:independence_wave_formable_member_country_entries^independence_wave_form48_cleanup_member_index = {
				if = {
					limit = {
						has_country_flag = independence_wave_form48_autonomous_member
						has_variable = independence_wave_form48_autonomous_carrier
						has_variable = independence_wave_form48_autonomous_carrier_generation
						has_variable = independence_wave_form48_autonomous_family
						# PREV is the carrier inside the member scope; origin cleanup
						# can run with ROOT set to another country.
						var:independence_wave_form48_autonomous_carrier = { tag = PREV.PREV }
						check_variable = { var = independence_wave_form48_autonomous_carrier_generation value = PREV.independence_wave_generation_id compare = equals }
						check_variable = { var = independence_wave_form48_autonomous_family value = PREV.independence_wave_formable_family compare = equals }
						check_variable = { var = independence_wave_generation_id value = PREV.independence_wave_formable_member_generation_entries^independence_wave_form48_cleanup_member_index compare = equals }
						has_independence_wave_form48_current_autonomous_binding = yes
					}
					independence_wave_form48_clear_autonomous_member_state = yes
				}
			}
			add_to_temp_variable = { independence_wave_form48_cleanup_member_index = constant:independence_wave_formable_tuning.loop_increment }
		}
	}
}

independence_wave_form48_install_autonomous_member = {
	save_event_target_as = independence_wave_form48_autonomous_member_target
	set_country_flag = independence_wave_form48_autonomous_member
	set_variable = { independence_wave_form48_autonomous_family = ROOT.independence_wave_formable_family }
	set_variable = { independence_wave_form48_autonomous_carrier = ROOT }
	set_variable = { independence_wave_form48_autonomous_carrier_generation = ROOT.independence_wave_generation_id }
	set_variable = { independence_wave_form48_autonomous_member_generation = independence_wave_generation_id }
	if = {
		limit = { NOT = { gives_military_access_to = ROOT } }
		give_military_access = ROOT
		set_country_flag = independence_wave_form48_member_granted_access_to_carrier
	}
	if = {
		limit = { NOT = { has_guaranteed = ROOT } }
		give_guarantee = ROOT
		set_country_flag = independence_wave_form48_member_guaranteed_carrier
	}
	ROOT = {
		if = {
			limit = { NOT = { gives_military_access_to = event_target:independence_wave_form48_autonomous_member_target } }
			give_military_access = event_target:independence_wave_form48_autonomous_member_target
			event_target:independence_wave_form48_autonomous_member_target = { set_country_flag = independence_wave_form48_carrier_granted_access_to_member }
		}
		if = {
			limit = { NOT = { has_guaranteed = event_target:independence_wave_form48_autonomous_member_target } }
			give_guarantee = event_target:independence_wave_form48_autonomous_member_target
			event_target:independence_wave_form48_autonomous_member_target = { set_country_flag = independence_wave_form48_carrier_guaranteed_member }
		}
		set_country_flag = independence_wave_form48_has_autonomous_members
	}
}

independence_wave_form48_remove_event6_autonomous_relations = {
	save_event_target_as = independence_wave_form48_cleanup_member
	if = {
		limit = {
			has_independence_wave_form48_current_autonomous_binding = yes
		}
		var:independence_wave_form48_autonomous_carrier = { save_event_target_as = independence_wave_form48_cleanup_carrier }
		if = {
			limit = { has_country_flag = independence_wave_form48_member_granted_access_to_carrier }
			diplomatic_relation = { country = event_target:independence_wave_form48_cleanup_carrier relation = military_access active = no }
		}
		if = {
			limit = { has_country_flag = independence_wave_form48_member_guaranteed_carrier }
			diplomatic_relation = { country = event_target:independence_wave_form48_cleanup_carrier relation = guarantee active = no }
		}
		if = {
			limit = { has_country_flag = independence_wave_form48_carrier_granted_access_to_member }
			event_target:independence_wave_form48_cleanup_carrier = {
				diplomatic_relation = { country = event_target:independence_wave_form48_cleanup_member relation = military_access active = no }
			}
		}
		if = {
			limit = { has_country_flag = independence_wave_form48_carrier_guaranteed_member }
			event_target:independence_wave_form48_cleanup_carrier = {
				diplomatic_relation = { country = event_target:independence_wave_form48_cleanup_member relation = guarantee active = no }
			}
		}
		event_target:independence_wave_form48_cleanup_carrier = {
			if = {
				limit = {
					has_country_flag = independence_wave_formable_active
					check_variable = { independence_wave_formable_family = constant:independence_wave_formable_family.pacific_regional_federation }
				}
				clr_country_flag = independence_wave_form48_all_autonomous_members_bound
				set_country_flag = independence_wave_form48_member_departed
			}
		}
	}
	clr_country_flag = independence_wave_form48_member_granted_access_to_carrier
	clr_country_flag = independence_wave_form48_member_guaranteed_carrier
	clr_country_flag = indepe
